"""Deliberately naive reference implementation of PROTOCOL.md.

Plain lists, whole-backlog scans and deepcopy checkpoints: correctness first,
used only to cross-check the optimized submission.
"""
import copy
from bisect import bisect_right

Q = 1048576


class Policy:
    def __init__(self, spec):
        self.kind = spec['kind']
        self.time = 0
        self.V = 0
        self.levels = {}
        self.weights = {}
        self.finish = {}
        if self.kind == 'sp':
            for flow, level in spec['levels']:
                self.levels[flow] = level
        elif self.kind == 'wfq':
            for flow, weight in spec['weights']:
                self.weights[flow] = weight
                self.finish[flow] = 0

    def rank(self, flow, length, flow_size):
        if self.kind == 'fifo':
            self.time += 1
            return self.time
        if self.kind == 'sp':
            return self.levels[flow]
        if self.kind == 'sff':
            return flow_size
        f = max(self.finish[flow], self.V) + (length * Q + self.weights[flow] - 1) // self.weights[flow]
        self.finish[flow] = f
        return f

    def post(self, rank):
        if self.kind == 'wfq' and rank > self.V:
            self.V = rank

    def certificate(self):
        if self.kind == 'fifo':
            return {'kind': 'fifo', 'time': self.time}
        if self.kind == 'sp':
            return {'kind': 'sp', 'levels': [[f, self.levels[f]] for f in sorted(self.levels)]}
        if self.kind == 'sff':
            return {'kind': 'sff'}
        return {'kind': 'wfq', 'virtual_time': self.V,
                'weights': [[f, self.weights[f]] for f in sorted(self.weights)],
                'finish': [[f, self.finish[f]] for f in sorted(self.finish)]}


class Ref:
    def __init__(self, cfg):
        self.M = cfg['banks']
        self.L = cfg['load_balancers']
        self.fifo_cap = cfg['fifo_bytes']
        self.pifo_cap = cfg['pifo_bytes']
        self.batch = cfg['refill_batch']
        self.period = cfg['sample_period']
        self.borders = list(cfg['borders'])
        R = len(self.borders) - 1
        self.policy = Policy(cfg['policy'])
        self.t = self.p = self.l = self.a = 0
        self.C = [[[1 if q < (r % self.M) else 0 for r in range(R)] for q in range(self.M)] for _ in range(self.L)]
        self.H = [0] * R
        self.fifos = [[] for _ in range(self.M)]
        self.pifos = [[] for _ in range(self.M)]
        self.fbytes = [0] * self.M
        self.pbytes = [0] * self.M
        self.live = {}

    # helpers
    def classify(self, rank):
        U = self.borders[-1]
        x = min(rank, U - 1)
        return bisect_right(self.borders, x) - 1

    def all_live(self):
        out = []
        for q in range(self.M):
            out.extend(self.fifos[q])
            out.extend(self.pifos[q])
        return out

    def sort_pifo(self, q):
        self.pifos[q].sort(key=lambda p: (p['rank'], p['oid']))

    def refill(self, q):
        k = min(self.batch, len(self.fifos[q]))
        if k == 0:
            return []
        moved = self.fifos[q][:k]
        del self.fifos[q][:k]
        for pkt in moved:
            self.fbytes[q] -= pkt['length']
            pkt['stage'] = 'pifo'
        extra = sum(p['length'] for p in moved)
        if self.pbytes[q] + extra <= self.pifo_cap:
            self.pifos[q].extend(moved)
            self.pbytes[q] += extra
            self.sort_pifo(q)
            return []
        merged = sorted(self.pifos[q] + moved, key=lambda p: (p['rank'], p['oid']))
        total = 0
        keep = 0
        for pkt in merged:
            if total + pkt['length'] > self.pifo_cap:
                break
            total += pkt['length']
            keep += 1
        evicted = merged[keep:]
        self.pifos[q] = merged[:keep]
        self.pbytes[q] = total
        out = []
        for pkt in sorted(evicted, key=lambda p: (p['rank'], p['oid']), reverse=True):
            del self.live[pkt['id']]
            out.append(pkt['id'])
        return out

    def sample(self):
        R = len(self.borders) - 1
        X = [0] * R
        for l in range(self.L):
            for q in range(self.M):
                for r in range(R):
                    X[r] += self.C[l][q][r]
        for l in range(self.L):
            for r in range(R):
                m = min(self.C[l][q][r] for q in range(self.M))
                for q in range(self.M):
                    self.C[l][q][r] -= m
        self.H = [self.H[r] // 2 + X[r] for r in range(R)]
        self.a = 0
        return X, list(self.H)

    def state(self):
        return {
            'tick': self.t, 'load_balancer': self.l, 'service_bank': self.p,
            'sample_progress': self.a, 'borders': list(self.borders),
            'counters': copy.deepcopy(self.C), 'history': list(self.H),
            'policy': self.policy.certificate(),
            'queues': [{'fifo': [p['id'] for p in self.fifos[q]],
                        'pifo': [p['id'] for p in self.pifos[q]],
                        'fifo_bytes': self.fbytes[q],
                        'pifo_bytes': self.pbytes[q]} for q in range(self.M)],
            'lags': sorted([[pid, self.live[pid]['lag']] for pid in self.live]),
        }

    def checkpoint(self):
        return copy.deepcopy({
            't': self.t, 'p': self.p, 'l': self.l, 'a': self.a,
            'C': self.C, 'H': self.H, 'borders': self.borders,
            'fifos': self.fifos, 'pifos': self.pifos,
            'fbytes': self.fbytes, 'pbytes': self.pbytes,
            'live': self.live, 'policy': self.policy.certificate(),
            'polraw': (self.policy.time, self.policy.V, self.policy.levels,
                       self.policy.weights, self.policy.finish),
        })

    def restore(self, ck):
        ck = copy.deepcopy(ck)
        self.t, self.p, self.l, self.a = ck['t'], ck['p'], ck['l'], ck['a']
        self.C, self.H, self.borders = ck['C'], ck['H'], ck['borders']
        self.fifos, self.pifos = ck['fifos'], ck['pifos']
        self.fbytes, self.pbytes = ck['fbytes'], ck['pbytes']
        self.live = ck['live']
        # packets are shared between the two views in the naive model: rebuild
        # references so stage structures and the live map agree
        for q in range(self.M):
            for pkt in self.fifos[q]:
                pkt['stage'] = 'fifo'
            for pkt in self.pifos[q]:
                pkt['stage'] = 'pifo'
        index = {}
        for q in range(self.M):
            for pkt in self.fifos[q] + self.pifos[q]:
                index[pkt['id']] = pkt
        self.live = index
        time, V, levels, weights, finish = ck['polraw']
        self.policy.time, self.policy.V = time, V
        self.policy.levels, self.policy.weights, self.policy.finish = levels, weights, finish

    def run(self, events):
        log = []
        saves = {}
        for i, cmd in enumerate(events):
            head = cmd[0]
            if head == 'enqueue':
                _, pid, flow, length, size = cmd
                rank = self.policy.rank(flow, length, size)
                r = self.classify(rank)
                l = self.l
                self.l = (l + 1) % self.L
                best, q = None, 0
                for cand in range(self.M):
                    v = self.C[l][cand][r]
                    if best is None or v < best:
                        best, q = v, cand
                accepted = self.fbytes[q] + length <= self.fifo_cap
                if accepted:
                    pkt = {'id': pid, 'flow': flow, 'length': length, 'size': size,
                           'rank': rank, 'oid': i, 'q': q, 'lag': 0, 'stage': 'fifo'}
                    self.fifos[q].append(pkt)
                    self.fbytes[q] += length
                    self.live[pid] = pkt
                    self.C[l][q][r] += 1
                    self.a += 1
                log.append([i, 'enqueue', pid, rank, l, r, q, accepted])
                if accepted and self.a == self.period:
                    X, H = self.sample()
                    log.append([i, 'sample', X, H])
            elif head == 'dequeue':
                for _ in range(cmd[1]):
                    q = self.p
                    self.p = (q + 1) % self.M
                    old = self.t
                    self.t = old + 1
                    served = None
                    evicted = []
                    if self.pifos[q]:
                        served = self.pifos[q].pop(0)
                        self.pbytes[q] -= served['length']
                        self.policy.post(served['rank'])
                        evicted = self.refill(q)
                    else:
                        evicted = self.refill(q)
                        if self.pifos[q]:
                            served = self.pifos[q].pop(0)
                            self.pbytes[q] -= served['length']
                            self.policy.post(served['rank'])
                    if served is None:
                        log.append([i, 'dequeue', old, q, None, None, 0, 0, evicted])
                        continue
                    rank = served['rank']
                    others = [p for p in self.all_live() if p is not served]
                    error = sum(1 for p in others if p['rank'] < rank)
                    lag = served['lag']
                    del self.live[served['id']]
                    for p in others:
                        if p['rank'] < rank:
                            p['lag'] += 1
                    log.append([i, 'dequeue', old, q, served['id'], rank, error, lag, evicted])
            elif head == 'sample':
                X, H = self.sample()
                log.append([i, 'sample', X, H])
            elif head == 'repartition':
                new = cmd[1]
                old = self.borders
                Rn = len(new) - 1

                def project(vec):
                    out = [0] * Rn
                    for idx in range(len(old) - 1):
                        m = vec[idx]
                        if not m:
                            continue
                        b = old[idx]
                        c = old[idx + 1]
                        span = c - b
                        for j in range(Rn):
                            u, v = new[j], new[j + 1]
                            hi = min(max(v - b, 0), span)
                            lo = min(max(u - b, 0), span)
                            out[j] += (m * hi) // span - (m * lo) // span
                    return out

                self.C = [[[0] * Rn for _ in range(self.M)] for _ in range(self.L)]
                for l in range(self.L):
                    for q in range(self.M):
                        self.C[l][q] = project_row = None
                newC = []
                for l in range(self.L):
                    lb = []
                    for q in range(self.M):
                        lb.append(project([self.C[l][q][idx] if False else 0 for idx in range(len(old) - 1)]))
                    newC.append(lb)
                self.C = newC
                self.borders = list(new)
                log.append([i, 'repartition', Rn])
            elif head == 'cancel':
                pid = cmd[1]
                pkt = self.live.get(pid)
                if pkt is None:
                    log.append([i, 'cancel', pid, None, None, None])
                    continue
                q = pkt['q']
                stage = pkt['stage']
                lag = pkt['lag']
                holder = self.fifos[q] if stage == 'fifo' else self.pifos[q]
                holder.remove(pkt)
                if stage == 'fifo':
                    self.fbytes[q] -= pkt['length']
                else:
                    self.pbytes[q] -= pkt['length']
                del self.live[pid]
                log.append([i, 'cancel', pid, stage, q, lag])
            elif head == 'inspect':
                pid = cmd[1]
                pkt = self.live.get(pid)
                if pkt is None:
                    log.append([i, 'inspect', pid, None])
                else:
                    log.append([i, 'inspect', pid, [pkt['rank'], pkt['q'], pkt['stage'],
                                                    pkt['length'], pkt['flow'], pkt['lag']]])
            elif head == 'weight':
                self.policy.weights[cmd[1]] = cmd[2]
                log.append([i, 'weight', cmd[1], cmd[2]])
            elif head == 'save':
                saves[cmd[1]] = self.checkpoint()
                log.append([i, 'save', cmd[1]])
            elif head == 'restore':
                self.restore(saves[cmd[1]])
                log.append([i, 'restore', cmd[1]])
        return {'log': log, 'state': self.state()}
PYEOF
